using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class TimelineEditorOperations
{
    private readonly ActorFileImportOperations _imports=new();
    public Settings prepare_actor_creation(Control owner,int index){_timelineCanvas.cancel_drag(Canvas(owner));var definitions=owner.Get("_definitions").AsGodotArray();if(index<0||index>=definitions.Count)return new Settings();var definition=definitions[index].As<Resource>();var prompts=new GArray();foreach(var value in definition.Get("properties").AsGodotArray()){var property=value.As<Resource>();var options=property.Get("options").AsGodotDictionary();if(!options.GetValueOrDefault("prompt_on_create",false).AsBool())continue;var picker=property;if(property.Get("object_type").AsString().Length>0){picker=new ActorProperty();picker.Set("id",property.Get("id"));picker.Set("label",property.Get("label"));picker.Set("value_type",(int)Variant.Type.String);picker.Set("options",new Settings{["extensions"]=options.GetValueOrDefault("prompt_extensions",new GArray()),["file_picker"]=true});}prompts.Add(new Settings{["property"]=property,["picker"]=picker,["title"]="Choose "+property.Get("label").AsString()+" for "+definition.Get("display_name").AsString()});}return new Settings{["definition"]=definition,["prompts"]=prompts,["values"]=new Settings()};}
    public bool actor_creation_choice(Control owner,Settings plan,Settings prompt,string chosen){var property=prompt["property"].As<Resource>();var key=property.Get("id").AsStringName();var values=plan["values"].AsGodotDictionary();if(chosen==GD.Load<GDScript>("res://scripts/actors/core/actor_project_file_picker.gd").GetScriptConstantMap()["EMPTY_RESOURCE"].AsString()){values[key]=default(Variant);return true;}if(chosen.Length==0){Canvas(owner).GrabFocus();return false;}if(property.Get("object_type").AsString().Length>0){var definition=_definitions.get_object_definition(owner.Get("registry").As<RefCounted>(),property.Get("object_type").AsStringName());string target=property.Get("options").AsGodotDictionary().GetValueOrDefault("prompt_object_property","").AsString();if(definition==null||target.Length==0||_definitions.find_property(definition,target)==null){Canvas(owner).GrabFocus();return false;}var data=_definitions.create_object(definition);_data.set_value(data,target,chosen);values[key]=_data.from_object(data);}else values[key]=chosen;return true;}
    public void finish_actor_creation(Control owner,Settings plan){var clip=_timeline.create_actor(Model(owner),plan["definition"].As<Resource>(),Time(owner),plan["values"].AsGodotDictionary());if(clip==null)return;Canvas(owner).GrabFocus();var vertical=owner.Get("v_scroll").As<VScrollBar>();vertical.Value=Math.Max(0,(clip.Get("layer").AsInt32()+1)*Canvas(owner).Get("row_height").AsDouble()-vertical.Page);var horizontal=owner.Get("h_scroll").As<HScrollBar>();double start=clip.Get("start_time").AsDouble();if(start<horizontal.Value||start>horizontal.Value+horizontal.Page)horizontal.Value=start;}
    public Settings prepare_drop(Control owner,string path,double time,int layer){string type=_imports.type_for_path(path).ToString();if(type=="scene_instance"){var source=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);var model=Model(owner);model.Set("selected_layer",layer);_timeline.instantiate_scene(model,ActorDataOperations.ScriptIs(source,"res://scripts/actors/core/actor_scene_data.gd")?source:null,_definitions.get_definition(owner.Get("registry").As<RefCounted>(),"point_3d"),time,layer,path.GetFile().GetBaseName(),"Instantiate Scene");return new Settings();}return new Settings{["type"]=type,["dimension"]=type is "image_3d" or "video" or "text_3d",["title"]=path.GetFile()};}
    public void finish_drop(Control owner,string path,double time,int layer,Settings plan,StringName dimension){string type=plan["type"].AsString();if(plan["dimension"].AsBool()){if(dimension.ToString().Length==0)return;if(dimension=="2d")type=type switch{"image_3d"=>"image_2d","video"=>"video_2d","text_3d"=>"text_2d",_=>type};}var registry=owner.Get("registry").As<RefCounted>();var definition=_definitions.get_definition(registry,type);if(definition==null)return;var model=Model(owner);model.Set("selected_layer",layer);var clip=_timeline.create_actor(model,definition,time,_imports.values_for_path(path,registry));if(clip!=null){var actor=_timeline.actor_for_id(model,clip.Get("actor_id").AsString());actor?.Set("display_name",path.GetFile().GetBaseName());model.EmitSignal("changed");}}
    public void finish_drops(Control owner){refresh(owner);Canvas(owner).GrabFocus();}
    public void inspect_project_resource(Control owner,string path){if(path.GetExtension().ToLowerInvariant() is "tres" or "res"){var resource=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_scene_data.gd"))return;}var inspector=owner.Get("inspector").As<Control>();if(inspector!=null)_inspector.inspect_file_resource(inspector,path);}
}
